// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  pub api_CurrentMode: SW::Mode,
}

/// container for component's incoming port values and GUMBO state variables
pub struct PreStateContainer_wGSV {
  pub In_malformedCount: i32,
  pub api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  pub api_CurrentMode: SW::Mode,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_EthernetFramesRxIn(container.api_EthernetFramesRxIn);
  put_CurrentMode(container.api_CurrentMode);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_container_wGSV(container: PreStateContainer_wGSV)
{
  put_malformedCount(container.In_malformedCount);
  put_EthernetFramesRxIn(container.api_EthernetFramesRxIn);
  put_CurrentMode(container.api_CurrentMode);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  CurrentMode: SW::Mode)
{
  put_EthernetFramesRxIn(EthernetFramesRxIn);
  put_CurrentMode(CurrentMode);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_wGSV(
  In_malformedCount: i32,
  EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  CurrentMode: SW::Mode)
{
  put_malformedCount(In_malformedCount);
  put_EthernetFramesRxIn(EthernetFramesRxIn);
  put_CurrentMode(CurrentMode);
}

/// setter for IN EventDataPort
pub fn put_EthernetFramesRxIn(value: Option<SW::StructuredEthernetMessage_i>)
{
  *extern_api::IN_EthernetFramesRxIn.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// getter for OUT EventDataPort
pub fn get_EthernetFramesRxOut() -> Option<SW::StructuredEthernetMessage_i>
{
  return extern_api::OUT_EthernetFramesRxOut.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

/// setter for IN DataPort
pub fn put_CurrentMode(value: SW::Mode)
{
  *extern_api::IN_CurrentMode.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_AttackStatusRx() -> SW::AttackStatus
{
  return extern_api::OUT_AttackStatusRx.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_malformedCount() -> i32
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.malformedCount,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_malformedCount(value: i32)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.malformedCount = value,
      None => panic!("The app is None")
    }
  }
}
